using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using KianaPet;
class UsabilityUiTests {
 static List<string> checks=new List<string>();static void Check(bool b,string n){if(!b)throw new Exception(n);checks.Add(n);}static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,v);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 static StackPanel Page(SettingsWindow w,string name){w.NavigateCategory(name,"");var tabs=(TabControl)Field(w,"settingsTabs");return (StackPanel)((ScrollViewer)((TabItem)tabs.SelectedItem).Content).Content;}
 static void Capture(Window w,string name){w.UpdateLayout();var b=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(w);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(Path.Combine(Store.Root,name+".png")))png.Save(f);}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);Store.Save(new Config{Walking=false,Gravity=false,LinkChatGPT=false,MusicEnabled=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,RememberLayouts=true});var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var pet=new PetWindow(true);bool success=false;
 pet.Loaded+=async delegate{try{await Task.Delay(500);var settings=app.Windows.OfType<SettingsWindow>().Single();Check(settings.ActiveCategory=="常用","设置默认常用分类");var nav=(ListBox)Field(settings,"categoryList");Check(nav.Items.Count>=10,"侧栏包含所有分类和新增页面");settings.Capture(Path.Combine(Store.Root,"settings-common.png"));settings.NavigateCategory("音乐","暂停");Check(settings.ActiveCategory=="音乐"&&nav.Items.Count>0,"搜索定位音乐暂停设置");Check(Page(settings,"音乐").Children.OfType<CheckBox>().Any(c=>(string)c.Content=="暂停时保留音乐卡片"),"音乐暂停卡片开关存在");settings.NavigateCategory("音乐","不存在的设置987");Check(((TextBlock)Field(settings,"searchEmpty")).Visibility==Visibility.Visible&&nav.Items.Count==0,"无匹配显示空结果提示");Page(settings,"外观与互动");var appearance=Page(settings,"外观与互动");int initial=pet.Settings.Size;appearance.Children.OfType<Slider>().First().Value=192;Check(pet.PendingUndo!=null&&pet.Settings.Size==192,"尺寸调整立即可撤销");pet.UndoLastEdit();await Task.Delay(100);settings=app.Windows.OfType<SettingsWindow>().Single();Check(pet.Settings.Size==initial&&settings.ActiveCategory=="外观与互动","撤销恢复尺寸并保留所在分类");pet.SetMusicPosition("right");pet.UndoLastEdit();await Task.Delay(100);settings=app.Windows.OfType<SettingsWindow>().Single();Check(pet.Settings.MusicPosition=="below","撤销恢复音乐栏布局模式");pet.Settings.Walking=true;pet.ApplySettings();settings.UpdateStatus();var common=Page(settings,"常用");Check(common.Children.OfType<CheckBox>().First().IsChecked==true,"常用开关随其他页面修改同步");pet.Settings.Walking=false;pet.ApplySettings();
 Call(pet,"RememberDisplay");string layouts=File.ReadAllText(Path.Combine(Store.Root,"display-layouts.json"));pet.ForgetDisplayLayouts();pet.UndoLastEdit();await Task.Delay(100);settings=app.Windows.OfType<SettingsWindow>().Single();Check(File.ReadAllText(Path.Combine(Store.Root,"display-layouts.json"))==layouts,"撤销恢复清除前的完整布局记忆");Page(settings,"最近调整");settings.Capture(Path.Combine(Store.Root,"settings-recent.png"));Check(((StackPanel)Field(settings,"recentPage")).Children.Count>2,"最近调整显示跳转入口");
 var access=Page(settings,"无障碍");var checkboxes=access.Children.OfType<CheckBox>().ToArray();checkboxes[0].IsChecked=true;checkboxes[1].IsChecked=true;Check(pet.Settings.ReduceMotion&&pet.Settings.LargeTouchTargets&&!MotionSettings.Enabled,"无障碍开关生效");var chat=(Button)Field(pet,"chatButton");Check(chat.Focusable&&chat.Width==42&&chat.Height==40,"工具栏键盘可聚焦并扩展触控区域");pet.FocusToolbar();await Task.Delay(100);Check((bool)Field(pet,"keyboardToolbarMode")&&chat.IsKeyboardFocused,"F6入口可实际聚焦工具栏");Call(pet,"ToolbarKey",pet,new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(pet),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});Check(!(bool)Field(pet,"keyboardToolbarMode"),"Esc结束工具栏键盘模式");settings.Activate();
 foreach(var info in pet.Pets.Where(x=>x.Id.EndsWith("-round"))){pet.SelectSkin(info.Id);foreach(string action in new[]{"groom","stretch"}){Set(pet,"state",action);pet.Settings.ReduceMotion=false;Call(pet,"DrawAnimation",300d);var sprite=(Image)Field(pet,"sprite");var frame=(BitmapSource)sprite.Source;Check(frame.PixelWidth==384&&frame.PixelHeight==416,info.Id+" "+action+" 新过渡帧实际载入");var first=sprite.Source;Call(pet,"DrawAnimation",1000d);Check(!object.ReferenceEquals(first,sprite.Source),info.Id+" "+action+" 从过渡进入已有动作");pet.Settings.ReduceMotion=true;Call(pet,"DrawAnimation",300d);first=sprite.Source;Call(pet,"DrawAnimation",1800d);Check(object.ReferenceEquals(first,sprite.Source),info.Id+" "+action+" 减少动态时固定姿态");}}
 pet.Settings.Theme="dark";pet.ApplySettings();Page(settings,"无障碍");settings.Capture(Path.Combine(Store.Root,"accessibility-dark.png"));var music=new MusicWindow(pet);music.Show();music.FocusControls();await Task.Delay(100);Check(music.KeyboardMode&&((Button)Field(music,"toggle")).IsKeyboardFocused,"音乐栏可用键盘实际聚焦播放按钮");var state=new MusicState{Connected=true,Title="这是一首用于检查完整歌名悬停展示与暂停状态的长标题",Artist="测试歌手",Playing=false,CanPrevious=true,CanToggle=true,CanNext=true};music.Refresh(state,"",null,false);Check(((TextBlock)Field(music,"artist")).Text.StartsWith("已暂停"),"暂停卡片明确显示状态");Check(((TextBlock)((ToolTip)((TextBlock)Field(music,"title")).ToolTip).Content).Text==state.Title,"悬停完整标题未截断");Check(music.Height==98&&((Button)Field(music,"toggle")).Height==34,"大触控音乐按钮使用额外布局高度");music.Capture(Path.Combine(Store.Root,"music-paused-dark.png"));pet.Settings.LargeTouchTargets=false;pet.Settings.Theme="light";pet.ApplySettings();music.Refresh(state,"",null,false);Check(music.Height==88,"默认音乐栏仍保持紧凑");music.Capture(Path.Combine(Store.Root,"music-paused-light.png"));music.Close();
 pet.TaskNotices.Publish(new TaskNotice{Source="测试来源",TaskId="a",Title="正在处理示例任务",Status="running"});pet.TaskNotices.Publish(new TaskNotice{Source="测试来源",TaskId="b",Title="示例任务完成",Status="succeeded"});pet.OpenNoticeCenter();await Task.Delay(200);var center=(NoticeCenter)Field(pet,"noticeCenter");Check(center.IsVisible&&pet.LocalNoticeCount==2,"通知中心显示本地任务和未读数量");((ComboBox)Field(center,"status")).SelectedIndex=2;Check(center.VisibleTaskCount==1,"界面状态筛选仅显示完成任务");Capture(center,"notification-center");pet.MuteSource("测试来源",true);Call(pet,"UpdateToolbar",0d);Check(pet.LocalNoticeCount==0&&((Button)Field(pet,"notificationButton")).Visibility==Visibility.Collapsed,"静音来源从铃铛未读移除");Check(pet.TaskNotices.Snapshot().Length==2,"静音后历史仍保留");center.Close();Check(Field(pet,"noticeCenter")==null&&!((System.Windows.Threading.DispatcherTimer)Field(center,"timer")).IsEnabled,"关闭通知中心释放引用和定时器");pet.OpenStorageManager();await Task.Delay(300);var storage=(StorageWindow)Field(pet,"storageWindow");Check(storage.IsVisible,"占用管理窗口可以打开");Capture(storage,"storage-manager");storage.Close();Check(Field(pet,"storageWindow")==null,"关闭占用管理释放窗口引用");
 success=true;}catch(Exception e){Store.Atomic("usability-ui-error.json",new{error=e.ToString()});}finally{Store.Atomic("usability-ui-tests.json",new{version="0.6.0",passed=success,checks=checks,physicalScreens=System.Windows.Forms.Screen.AllScreens.Length});pet.Close();}};app.Run(pet);return success?0:1;}
}
